def blob(ref):
    r = subprocess.run(["git", "show", ref], capture_output=True, cwd=ROOT)
    if r.returncode:
        sys.exit("cannot read %s: %s" % (ref, r.stderr.decode("utf-8", "replace").strip()))
    return r.stdout.decode("utf-8")          # bytes -> str; never $(...) which eats trailing newlines


def worktree(rel):
    with open("%s/%s" % (ROOT, rel), encoding="utf-8", newline="") as fh:
        return fh.read()


def added_at(rel):
    """The commit that ADDED `rel`, or "" if git does not know of one."""
    return subprocess.run(["git", "log", "--diff-filter=A", "-1", "--format=%H", "--", rel],
                          capture_output=True, text=True, cwd=ROOT).stdout.strip()


def scan(lines):
    inside = False
    for i, raw in enumerate(lines):
        s = raw.rstrip("\r\n")
        if s.startswith("```") or s.startswith("~~~"):
            yield i, s, inside
            inside = not inside
            continue
        yield i, s, inside


def zones(text):
    """-> (front, [record, ...], lines). A record is a heading-delimited BYTE SPAN, never a session."""
    lines = text.splitlines(keepends=True)
    st = [i for i, s, ins in scan(lines) if not ins and RECORD_START.match(s)]
    if not st:
        return text, [], lines
    front = "".join(lines[:st[0]])
    bounds = st + [len(lines)]
    return front, ["".join(lines[a:b]) for a, b in zip(st, bounds[1:])], lines


def label(rec):
    for ln in rec.splitlines():
        if ln.strip():
            return ln.strip()[:90]
    return "(empty record)"


def ids(recs):
    """The session id captured from each record's own heading line, in order."""
    return tuple(RECORD_START.match(r.splitlines()[0]).group(1) for r in recs)


def declared(before_front, subst=None):
    """The front matter this trim is ALLOWED to produce, before the pointer is inserted."""
    for old, new in (FRONT_SUBST if subst is None else subst):
        before_front = before_front.replace(old, new, 1)
    return before_front


# One canonical clause shape, so all three copies of the table parse with one regex.
ROUTE_CLAUSE = re.compile(r"\*\*(?:(\d+) ≤ N ≤ (\d+)|N ≤ (\d+)|N ≥ (\d+))\*\* → `([^`]+)`")


def parse_table(text):
    out = []
    for a, b, le, ge, dest in ROUTE_CLAUSE.findall(text):
        if a:
            out.append((int(a), int(b), dest))
        elif le:
            out.append((None, int(le), dest))
        else:
            out.append((int(ge), None, dest))
    return tuple(out)


_ID_CACHE = {}


def numeric_ids(dest, after, shard, sha):
    """The numeric session ids actually present in the file `dest` names."""
    if dest == LIVE:
        text = after
    elif dest == SHARD.rsplit("/", 1)[1]:
        text = shard
    else:
        key = (dest, sha)
        if key not in _ID_CACHE:
            path = ARCHIVE_DIR + dest
            try:
                _ID_CACHE[key] = blob("%s:%s" % (sha, path)) if sha else worktree(path)
            except (SystemExit, OSError):
                _ID_CACHE[key] = None
        text = _ID_CACHE[key]
        if text is None:
            return None
    return sorted(int(i) for i in ids(zones(text)[1]) if i.isdigit())


# =====================================================================================
# The assertions. Each returns a list of failure strings; empty == holds.
# =====================================================================================

def L0(name, text):
    """footer_mode='none' asserted: no standalone `---` after the last record start may carry
    content below it. In a newest-on-top ledger the footer sits exactly where an oldest-first cut
    takes from, so 'none' must mean 'I looked', not 'I did not look'."""
    front, recs, lines = zones(text)
    if not recs:
        return ["L0 %s: no records found — grammar mismatch" % name]
    last = [i for i, s, ins in scan(lines) if not ins and RECORD_START.match(s)][-1]
    out = []
    for i, s, ins in scan(lines):
        if not ins and i > last and s.strip() == "---":
            tail = "".join(lines[i + 1:])
            if tail.strip():
                out.append("L0 %s: trailing file-scoped block at line %d (%d B): %.400s"
                           % (name, i + 1, len(tail.encode()), tail))
    return out


def L1(before_recs, after_recs, shard_recs):
    """Concatenation identity scoped to the RECORDS zone. Operand order is load-bearing: this
    ledger is newest-on-top and the cut takes from the bottom, so retained precedes archived. No
    invert step — TRANSFORM is None, which makes this the strongest form. It is ALSO what makes
    L2/b3's records half redundant — the fifth trim's condition, re-checked at this cut."""
    got = "".join(after_recs) + "".join(shard_recs)
    want = "".join(before_recs)
    if got == want:
        return []
    i = next((n for n, (a, b) in enumerate(zip(got, want)) if a != b), min(len(got), len(want)))
    return ["L1: records-zone concatenation differs at character %d "
            "(retained+archived %d B vs before %d B)"
            % (i, len(got.encode()), len(want.encode()))]


def L2(before_front, after_front, shard_front, shard_recs, pointer, subst):
    out = []
    for k, (old, _new) in enumerate(subst, 1):
        if before_front.count(old) != 1:
            out.append("L2/b0 SUBSTITUTION %d NOT UNIQUELY ANCHORED: its source text occurs %d "
                       "times in the before front matter (want exactly 1) — the declaration has "
                       "gone stale against the file it claims to describe" % (k, before_front.count(old)))
    want_front = declared(before_front, subst)
    if pointer not in after_front:
        out.append("L2_POINTER_MISSING: the declared pointer block is not in the live front matter "
                   "verbatim — a severed record set with no pointer to its shard")
    else:
        residue = after_front.replace(pointer, "", 1)
        if residue != want_front:
            i = next((n for n, (a, b) in enumerate(zip(residue, want_front)) if a != b),
                     min(len(residue), len(want_front)))
            out.append("L2/b1 CONFINEMENT: live front matter changed beyond the declared pointer "
                       "insertion + the %d declared substitutions; first divergence at character "
                       "%d (%d B residue vs %d B declared)"
                       % (len(subst), i, len(residue.encode()), len(want_front.encode())))
    after_set = set(after_front.splitlines())
    for ln in want_front.splitlines():
        if ln.strip() and ln not in after_set:      # exact membership, never substring (BL-28)
            out.append("L2/b2 SURVIVAL: front-matter line vanished: %r" % ln[:120])
    # b3 NO-LEAK, narrowed to the BANNER by the fifth trim and carried forward unchanged.
    for ln in before_front.splitlines():
        s = ln.strip()
        if len(s) > 24 and s in shard_front:
            out.append("L2/b3 NO-LEAK: front-matter line leaked into the shard's banner: %r" % s[:120])
    return out


def noleak_note(before_front, shard_recs):
    """NOT an assertion. The lines the pre-narrowing b3 would have flagged in the records half."""
    body = "".join(shard_recs)
    return [(i, ln.strip()) for i, ln in enumerate(before_front.splitlines(), 1)
            if len(ln.strip()) > 24 and ln.strip() in body]


def L3(before_recs, after_recs, shard_recs):
    """Per-record partition by identity, ORDER and byte-equality."""
    have = Counter(after_recs) + Counter(shard_recs)
    before_c = Counter(before_recs)
    absent = list((before_c - have).elements())
    added = list((have - before_c).elements())
    out = []
    for r in absent:
        out.append("L3 MISSING: a record from `before` is in neither artifact "
                   "(dropped, or edited so its original bytes exist nowhere): %s" % label(r))
    for r in added:
        # Project strengthening: this design forbids bundling any record edit into the trim commit
        # (three commits, by rule — claim, trim, close-out), so a non-zero added count means the
        # rule was broken. Deliberate divergence from the canonical tool.
        out.append("L3 ADDED: a record exists that was not in `before` — the trim commit "
                   "bundled a record edit: %s" % label(r))
    if not absent and not added:
        rebuilt, pool = [], Counter(added)
        for r in after_recs + shard_recs:
            if pool[r]:
                pool[r] -= 1
                continue
            rebuilt.append(r)
        bad = [i for i, (a, b) in enumerate(zip(before_recs, rebuilt)) if a != b]
        if bad or len(rebuilt) != len(before_recs):
            out.append("L3 ORDER: records out of order at indices %s" % bad[:12])
    return out


def L4(after_recs, shard_recs):
    """The cut point itself, against the HAND-DECLARED cut key."""
    out = []
    got_a, got_s = ids(after_recs), ids(shard_recs)
    if got_a != CUT_RETAINED:
        out.append("L4 CUT/retained: the live file holds Sessions %s; the declared cut key says %s"
                   % (list(got_a), list(CUT_RETAINED)))
    if got_s != CUT_ARCHIVED:
        out.append("L4 CUT/archived: the shard holds Sessions %s; the declared cut key says %s"
                   % (list(got_s), list(CUT_ARCHIVED)))
    return out


def L5(after_front, shard_front, claude, after, shard, sha, routing):
    """Routing coherence — the sentence a human acts on: which file to open for Session N."""
    out = []
    lo_a, hi_a = min(map(int, CUT_ARCHIVED)), max(map(int, CUT_ARCHIVED))
    lo_r = min(map(int, CUT_RETAINED))
    shard_base = SHARD.rsplit("/", 1)[1]

    for who, text in (("live pointer", after_front), ("shard banner", shard_front),
                      ("CLAUDE.md", claude)):
        got = parse_table(text)
        if got != routing:
            out.append("L5/1 %s: its routing table parses to %s; the declaration says %s"
                       % (who, list(got), list(routing)))

    below = [c for c in routing if c[0] is None]
    above = [c for c in routing if c[1] is None]
    if len(below) != 1 or len(above) != 1 or routing[0][0] is not None or routing[-1][1] is not None:
        out.append("L5/2 shape: want exactly one open-below clause first and one open-above clause "
                   "last; got %d and %d in %s" % (len(below), len(above), list(routing)))
    else:
        edge = routing[0][1]
        for lo, hi, dest in routing[1:-1]:
            if lo != edge + 1:
                out.append("L5/2 %s at %d-%d (`%s`): the preceding clause ends at %d"
                           % ("GAP" if lo > edge + 1 else "OVERLAP", lo, hi, dest, edge))
            edge = hi
        if routing[-1][0] != edge + 1:
            out.append("L5/2 %s between the last range (ends %d) and `N >= %d` (`%s`)"
                       % ("GAP" if routing[-1][0] > edge + 1 else "OVERLAP", edge,
                          routing[-1][0], routing[-1][2]))

    mine = [c for c in routing if c[2] == shard_base]
    live = [c for c in routing if c[2] == LIVE]
    if len(mine) != 1 or mine[0][:2] != (lo_a, hi_a):
        out.append("L5/3 shard clause: the table routes %s to `%s`; this cut archived Sessions "
                   "%d-%d" % ([c[:2] for c in mine], shard_base, lo_a, hi_a))
    if len(live) != 1 or live[0][:2] != (lo_r, None):
        out.append("L5/3 live clause: the table routes %s to `%s`; this cut retained Sessions "
                   "%d and up" % ([c[:2] for c in live], LIVE, lo_r))

    for lo, hi, dest in routing:
        found = numeric_ids(dest, after, shard, sha)
        if found is None:
            out.append("L5/4 `%s`: the table routes Sessions %s-%s here and the file cannot be "
                       "read" % (dest, lo, hi))
            continue
        if not found:
            out.append("L5/4 `%s`: no numeric session ids found — the check would pass vacuously"
                       % dest)
            continue
        stray = [n for n in found if (lo is not None and n < lo) or (hi is not None and n > hi)]
        if stray:
            out.append("L5/4 `%s`: routed Sessions %s-%s, but it actually contains %s (ids %d-%d)"
                       % (dest, lo, hi, stray[:8], found[0], found[-1]))
    return out


def L6(shard_front, banner):
    """The shard banner, pinned byte-for-byte — the shard-side analogue of L2/b1."""
    if shard_front == banner:
        return []
    i = next((n for n, (a, b) in enumerate(zip(shard_front, banner)) if a != b),
             min(len(shard_front), len(banner)))
    return ["L6 BANNER: the shard's banner is not the declared text; first divergence at character "
            "%d (%d B in the shard vs %d B declared)"
            % (i, len(shard_front.encode()), len(banner.encode()))]


def L7(sha, shard_blob, disk):
    """Write-once, enforced, for THIS shard. Applicability is decided by `disk` ALONE."""
    if disk is NA:
        return []
    if disk is MISSING:
        return ["L7 WRITE-ONCE: the shard is GONE from the working tree. Every assertion above "
                "still passes because they read git history at the trim commit — this one is the "
                "reason you found out."]
    if disk != shard_blob:
        i = next((n for n, (a, b) in enumerate(zip(disk, shard_blob)) if a != b),
                 min(len(disk), len(shard_blob)))
        return ["L7 WRITE-ONCE: the shard on disk is not the shard committed at %s; first "
                "divergence at character %d (%d B on disk vs %d B committed). Shards are "
                "write-once; this file was edited after its trim."
                % (sha[:7] if sha else "the trim commit", i,
                   len(disk.encode()), len(shard_blob.encode()))]
    return []


def L8(reach_texts, routing):
    """The copies that live outside every earlier proof. Both halves matter and neither subsumes
    the other. `routing` is the DECLARED table, taken from the same override L5 reads."""
    out = []
    want_names = {d for _lo, _hi, d in routing if d != LIVE}
    for path, required, forbidden in REACH:
        text = reach_texts.get(path)
        if text is None:
            out.append("L8 `%s`: unreadable, so no copy of the shard set in it can be checked"
                       % path)
            continue
        for s in required:
            if s not in text:
                out.append("L8/required `%s`: this trim declares it must contain %r and it does "
                           "not — the copy no earlier proof could reach is now stale" % (path, s[:90]))
        for s in forbidden:
            if s in text:
                out.append("L8/forbidden `%s`: it still contains %r, which this trim falsified"
                           % (path, s[:90]))
        got_names = set(SHARD_NAME.findall(text))
        if got_names != want_names:
            out.append("L8/set `%s`: it names shards %s; ROUTING names %s (missing %s; unknown %s)"
                       % (path, sorted(got_names), sorted(want_names),
                          sorted(want_names - got_names) or "none",
                          sorted(got_names - want_names) or "none"))
    return out


def L9(lineage):
    """Write-once for the WHOLE lineage. Each ancestor is compared against the blob committed at
    the commit that ADDED it — its own commit, never this trim's."""
    out = []
    for path, committed, disk in lineage:
        if committed is None:
            out.append("L9 `%s`: git knows no commit that added it, so there is nothing to hold "
                       "the working tree against" % path)
            continue
        if disk is MISSING:
            out.append("L9 WRITE-ONCE `%s`: GONE from the working tree. The routing table still "
                       "sends readers here and every byte assertion above still passes, because "
                       "they read history." % path)
            continue
        if disk != committed:
            i = next((n for n, (a, b) in enumerate(zip(disk, committed)) if a != b),
                     min(len(disk), len(committed)))
            out.append("L9 WRITE-ONCE `%s`: on disk it is not the file that was committed; first "
                       "divergence at character %d (%d B on disk vs %d B committed). Shards are "
                       "write-once — this one was edited after its own trim."
                       % (path, i, len(disk.encode()), len(committed.encode())))
    return out


def L10(provenance):
    """The ancestors' PROOFS, held against hand-declared freeze commits. A weakened ancestor proof
    is worse than a deleted one: it still exits 0."""
    out = []
    for path, freeze, committed, disk in provenance:
        if committed is None:
            out.append("L10 `%s`: the declared freeze commit %s does not hold this path, so there "
                       "is nothing to compare the working tree against — the declaration is wrong, "
                       "or the history was rewritten" % (path, freeze[:7]))
            continue
        if disk is MISSING:
            out.append("L10 PROVENANCE `%s`: GONE from the working tree. Its shard is still here "
                       "and L9 still passes on it; seven banners and a routing table still tell "
                       "readers to run this proof, and there is nothing left to run." % path)
            continue
        if disk != committed:
            i = next((n for n, (a, b) in enumerate(zip(disk, committed)) if a != b),
                     min(len(disk), len(committed)))
            out.append("L10 PROVENANCE `%s`: on disk it is not the proof frozen at %s; first "
                       "divergence at character %d (%d B on disk vs %d B frozen). An ancestor "
                       "proof was edited after its session ended — if that edit weakened it, it "
                       "still exits 0."
                       % (path, freeze[:7], i, len(disk.encode()), len(committed.encode())))
    return out


def L11(before, after, after_recs, claude, policy):
    """The retention rule this cut exists to satisfy. L0-L10 all ask whether the trim was performed
    FAITHFULLY; none asks whether it was performed AT ALL."""
    trigger, target, floor, texts = policy
    out = []
    nb, na = len(before.splitlines()), len(after.splitlines())
    if nb <= trigger:
        out.append("L11/fire: the live file was %d lines before this cut; the declared trigger is "
                   "more than %d, so this trim should not have fired" % (nb, trigger))
    if na > target:
        out.append("L11/target: the live file is %d lines after this cut; the declared target is "
                   "at most %d — the cut was too shallow to solve the problem that fired it"
                   % (na, target))
    if len(after_recs) < floor:
        out.append("L11/floor: the live file retains %d records; the declared floor is %d — the "
                   "cut was too deep and took working context with it" % (len(after_recs), floor))
    for n, s in zip((trigger, target, floor), texts):
        if s not in claude:
            out.append("L11/declared: `CLAUDE.md` no longer states %r, so the numbers this "
                       "assertion enforces are no longer the numbers the project declares" % s[:90])
        elif "{:,}".format(n) not in s:
            out.append("L11/figure: this assertion enforces %d, but the sentence it cites — %r — "
                       "states a different figure. The integer is anchored to nothing, and a trim "
                       "can legitimise a bad cut by typing a new one." % (n, s[:90]))
    return out


def L12(after_front, shard_front, shard, after_recs, shard_recs, reach_texts, sizes, prose):
    """ARITHMETIC. Every number this trim states about the SIZE of ITS OWN artifacts."""
    out = []
    measured = {
        "archived_headings": len(shard_recs),
        "archived_lines":    len("".join(shard_recs).splitlines()),
        "shard_total":       len(shard.splitlines()),
        "retained_records":  len(after_recs),
        "read_cap":          sizes["read_cap"],
        "mutants":           sizes["mutants"],
    }
    for key in ("archived_headings", "archived_lines", "shard_total", "retained_records"):
        if sizes[key] != measured[key]:
            out.append("L12/%s: this trim declares %s = %d; the artifacts measure %d — a figure "
                       "was typed rather than derived"
                       % (key, key, sizes[key], measured[key]))
    if measured["shard_total"] >= sizes["read_cap"]:
        out.append("L12/cap: the shard is %d lines and the declared agent read cap is %d — the "
                   "banner's claim that it sits under the cap is false, and a `Read` of it "
                   "truncates in silence" % (measured["shard_total"], sizes["read_cap"]))
    texts = {"live pointer": after_front, "shard banner": shard_front}
    texts.update(reach_texts)
    for where, literal, form, keys in prose:
        text = texts.get(where)
        if text is None:
            out.append("L12/prose `%s`: unreadable, so the size figures in it cannot be checked"
                       % where)
            continue
        n = text.count(literal)
        if n == 0:
            out.append("L12/prose `%s`: this trim declares it states %r and it does not — the "
                       "sentence and the artifact have diverged" % (where, literal[:90]))
            continue
        if n > 1:
            out.append("L12/unique `%s`: the declared literal %r occurs %d times, so this arm is "
                       "satisfied by whichever copy it finds and the load-bearing one can go stale "
                       "green. Anchor the literal to the sentence that matters."
                       % (where, literal[:90], n))
            continue
        for key in keys:
            want = WORDS.get(measured[key]) if form == "word" else "{:,}".format(measured[key])
            if want is None or want not in literal:
                out.append("L12/prose `%s`: %r claims %s but the artifacts measure %s (%r) — the "
                           "prose is stated in a figure nobody derived"
                           % (where, literal[:70], key, measured[key], want))
    return out


def L13(after_front, shard_front, reach_texts, after_recs, shard_recs,
        base, form, prose, census):
    """NAME AND SPAN, for THIS cut. The shard's own FILENAME, and every sentence stating which
    sessions moved, held against the record ids actually present in the two files.

    The CENSUS arm gained a UNIQUENESS test at this trim, and it was not cosmetic: the seventh
    trim's own pointer block is still in this file's front matter and still says "**eight declared
    sentences** stating which sessions moved". A membership test over the whole front matter cannot
    tell that copy from this cut's. Wording around the collision is not a fix; count == 1 is."""
    out = []
    arch, ret = ids(shard_recs), ids(after_recs)
    if not arch or not ret:
        return ["L13: a records zone is empty — there is no span to derive"]
    spans = {"archived": (arch[0], arch[-1]), "retained": (ret[0], ret[-1])}
    want_name = form % spans["archived"]
    if base != want_name:
        out.append("L13/name: this trim names its shard `%s`, but the records inside it are "
                   "Sessions %s-%s, which the naming rule makes `%s`. A filename is the first "
                   "routing information a reader sees and it disagrees with the file."
                   % (base, spans["archived"][0], spans["archived"][1], want_name))
    texts = {"live pointer": after_front, "shard banner": shard_front}
    texts.update(reach_texts)
    for where, literal, sep, which in prose:
        text = texts.get(where)
        if text is None:
            out.append("L13/prose `%s`: unreadable, so the span sentences in it cannot be checked"
                       % where)
            continue
        n = text.count(literal)
        if n == 0:
            out.append("L13/prose `%s`: this trim declares it states %r and it does not — the "
                       "sentence and the artifact have diverged" % (where, literal[:90]))
            continue
        if n > 1:
            out.append("L13/unique `%s`: the declared literal %r occurs %d times, so a stale copy "
                       "of the span can satisfy this arm while the sentence that matters is wrong"
                       % (where, literal[:90], n))
            continue
        want = "%s%s%s" % (spans[which][0], sep, spans[which][1])
        if want not in literal:
            out.append("L13/span `%s`: %r states an %s span that the records do not have; they "
                       "measure %r — a span was typed rather than derived"
                       % (where, literal[:70], which, want))
    c = after_front.count(census)
    if c == 0:
        out.append("L13/census-absent: the pointer block no longer states %r, so the count a "
                   "reader trusts about this assertion's reach is not in the file at all"
                   % census[:90])
    elif c > 1:
        out.append("L13/census-unique: %r occurs %d times in the front matter, so this arm is "
                   "satisfied by whichever copy it finds — and an earlier trim's pointer block is "
                   "still in this file saying something very like it" % (census[:90], c))
    else:
        want = WORDS.get(len(prose))
        if want is None or want not in census:
            out.append("L13/census: the pointer block tells a reader L13 holds %r, but it reads "
                       "%d sentence(s) — that count was typed, not derived"
                       % (census[:90], len(prose)))
    return out


def L14(after_front, reach_texts, lineage, routing, prose, census):
    """LINEAGE FIGURES. Every ANCESTOR shard's span and size figure, in the four files L8 reaches.

    L12 and L13 are scoped to the cut that ships them BY CONSTRUCTION — they measure the two files
    in hand. So the moment the next trim lands, the shard they guarded becomes an ancestor and its
    figures fall out of every assertion's reach permanently. Seven trims' worth had accumulated.

    Three halves, and none can satisfy another. The SET half holds the shards the declared literals
    are about against ROUTING's ancestor set — that is the arm that stops the NEXT trim reopening
    this, because it cannot inherit this declaration unchanged and be green. The PROSE half derives
    each figure from the ancestor shard AT ITS OWN ADD-COMMIT (never the working tree: L9 proves
    disk == add-commit, so reading disk would make L14 silently depend on L9) and holds it against
    the literal. The CENSUS arm holds this assertion's claim about its own reach against what it
    actually reads, and — like L13's — asserts that claim occurs exactly once."""
    out = []
    # measure every ancestor from its own add-commit blob
    facts = {}
    for path, committed, _disk in lineage:
        base = path.rsplit("/", 1)[1]
        if committed is None:
            continue                       # unmeasurable; the blob arm below reports it
        recs = zones(committed)[1]
        if not recs:
            continue
        i = ids(recs)
        facts[base] = {"span": (i[0], i[-1]),
                       "total": len(committed.splitlines()),
                       "record_lines": len("".join(recs).splitlines())}

    want_shards = {d for _lo, _hi, d in routing
                   if d != LIVE and d != SHARD.rsplit("/", 1)[1]}
    got_shards = {s for _w, _l, _sep, pairs in prose for s, _f in pairs}
    if got_shards != want_shards:
        out.append("L14/set: the declared literals are about shards %s; ROUTING's ancestor set is "
                   "%s (missing %s; unknown %s). A shard whose figures no literal here mentions is "
                   "described by prose nothing derives — which is the whole hole this assertion "
                   "closes, reopened."
                   % (sorted(got_shards), sorted(want_shards),
                      sorted(want_shards - got_shards) or "none",
                      sorted(got_shards - want_shards) or "none"))

    texts = dict(reach_texts)
    for where, literal, sep, pairs in prose:
        text = texts.get(where)
        if text is None:
            out.append("L14/prose-unreadable `%s`: unreadable, so the ancestor figures in it "
                       "cannot be checked" % where)
            continue
        n = text.count(literal)
        if n == 0:
            out.append("L14/prose `%s`: this trim declares it states %r and it does not — the "
                       "sentence and the ancestor it describes have diverged"
                       % (where, literal[:90]))
            continue
        if n > 1:
            out.append("L14/unique `%s`: the declared literal %r occurs %d times, so a stale copy "
                       "can satisfy this arm while the load-bearing one is wrong"
                       % (where, literal[:90], n))
            continue
        for base, field in pairs:
            f = facts.get(base)
            if f is None:
                # Covers both "git knows no add-commit for it" and "the declaration names a shard
                # the lineage does not contain". Reported, never skipped: a figure held against
                # nothing is the state this assertion exists to end.
                out.append("L14/blob `%s`: `%s` cannot be measured at its own add-commit, so the "
                           "figure %r states about it is held against nothing"
                           % (where, base, literal[:60]))
                continue
            if field == "span":
                want = "%s%s%s" % (f["span"][0], sep, f["span"][1])
            else:
                want = "{:,}".format(f[field])
            if want not in literal:
                out.append("L14/%s `%s`: %r states a %s for `%s` that the shard does not have; "
                           "measured at its own add-commit it is %r — an ancestor figure was "
                           "typed rather than derived"
                           % ("span" if field == "span" else "size",
                              where, literal[:70], field, base, want))
    # COMPLETENESS. Every arm above checks a literal the trim DECLARED. This one checks that the
    # declaration is not MISSING one: it scans each text for every ancestor's span and size figure
    # and requires each occurrence to fall inside a declared literal. Without it, L14 proves only
    # that the figures someone chose to list are right — which is exactly how the seventh trim's
    # bequest came to under-count its own subject, and how this trim's first draft shipped 44
    # declared against 45 present. Learning #126 ("the list was written by someone who had not run
    # it") mechanised, one field at a time.
    for where in sorted(texts):
        text = texts[where]
        if text is None:
            continue                       # already reported by the unreadable arm above
        covered = []
        for _w, lit, _s, _p in prose:
            if _w != where:
                continue
            i = 0
            while True:
                j = text.find(lit, i)
                if j < 0:
                    break
                covered.append((j, j + len(lit)))
                i = j + 1
        for base in sorted(facts):
            f = facts[base]
            pats = [(re.escape("%s%s%s" % (f["span"][0], s, f["span"][1])), "span")
                    for s in ("→", "->")]
            pats += [(re.escape("{:,}".format(f[k])), k) for k in ("total", "record_lines")]
            for pat, kind in pats:
                for m in re.finditer(r"(?<![\d.,])%s(?![\d])" % pat, text):
                    if any(a <= m.start() and m.end() <= b for a, b in covered):
                        continue
                    out.append("L14/complete `%s`: at character %d it states `%s`'s %s (%r) "
                               "outside every declared literal — an ancestor figure the "
                               "declaration does not reach, which is the defect this assertion "
                               "exists to end: ...%s..."
                               % (where, m.start(), base, kind, m.group(0),
                                  text[max(0, m.start() - 40):m.end() + 25].replace("\n", " ")))
    c = after_front.count(census)
    if c == 0:
        out.append("L14/census-absent: the pointer block no longer states %r, so the count a "
                   "reader trusts about this assertion's reach is not in the file at all"
                   % census[:90])
    elif c > 1:
        out.append("L14/census-unique: %r occurs %d times in the front matter, so this arm is "
                   "satisfied by whichever copy it finds" % (census[:90], c))
    else:
        figures = sum(len(pairs) for _w, _l, _s, pairs in prose)
        for n_, what in ((len(prose), "literals"), (figures, "figures")):
            if str(n_) not in census:
                out.append("L14/census: the pointer block tells a reader L14 holds %r, but it "
                           "reads %d %s — that count was typed, not derived"
                           % (census[:90], n_, what))
    return out


def check(before, after, shard, claude, sha, disk, reach_texts, lineage, provenance, decl=None):
    d = {"POINTER": POINTER, "BANNER": BANNER, "ROUTING": ROUTING, "POLICY": POLICY,
         "SIZES": SIZES, "SIZE_PROSE": SIZE_PROSE, "SHARD_BASE": SHARD_BASE,
         "NAME_FORM": NAME_FORM, "SPAN_PROSE": SPAN_PROSE, "SPAN_CENSUS": SPAN_CENSUS,
         "FRONT_SUBST": FRONT_SUBST, "LINEAGE_PROSE": LINEAGE_PROSE,
         "LINEAGE_CENSUS": LINEAGE_CENSUS}
    if decl:
        d.update(decl)
    bf, br, _ = zones(before)
    af, ar, _ = zones(after)
    sf, sr, _ = zones(shard)
    fails = []
    fails += L0("before", before) + L0("after", after) + L0("shard", shard)
    fails += L1(br, ar, sr)
    fails += L2(bf, af, sf, sr, d["POINTER"], d["FRONT_SUBST"])
    fails += L3(br, ar, sr)
    fails += L4(ar, sr)
    fails += L5(af, sf, claude, after, shard, sha, d["ROUTING"])
    fails += L6(sf, d["BANNER"])
    fails += L7(sha, shard, disk)
    fails += L8(reach_texts, d["ROUTING"])
    fails += L9(lineage)
    fails += L10(provenance)
    fails += L11(before, after, ar, claude, d["POLICY"])
    fails += L12(af, sf, shard, ar, sr, reach_texts, d["SIZES"], d["SIZE_PROSE"])
    fails += L13(af, sf, reach_texts, ar, sr, d["SHARD_BASE"], d["NAME_FORM"], d["SPAN_PROSE"], d["SPAN_CENSUS"])  # one line on purpose: the neuter loop replaces it with `pass`
    fails += L14(af, reach_texts, lineage, d["ROUTING"], d["LINEAGE_PROSE"], d["LINEAGE_CENSUS"])
    return fails, (br, ar, sr)


# =====================================================================================
def artifacts():
    sha = added_at(SHARD)

    # L9's and L14's operands never depend on `sha`: each ancestor is held against ITS OWN
    # add-commit, so both are applicable before this trim is committed at all.
    lineage = []
    for path in ANCESTORS:
        a = added_at(path)
        committed = blob("%s:%s" % (a, path)) if a else None
        try:
            on_disk = worktree(path)
        except OSError:
            on_disk = MISSING
        lineage.append((path, committed, on_disk))
    lineage = tuple(lineage)

    # L10's operands never depend on `sha` either: each ancestor proof is held against its own
    # HAND-DECLARED freeze commit.
    provenance = []
    for path, freeze in ANCESTOR_PROOFS:
        try:
            committed = blob("%s:%s" % (freeze, path))
        except SystemExit:
            committed = None
        try:
            on_disk = worktree(path)
        except OSError:
            on_disk = MISSING
        provenance.append((path, freeze, committed, on_disk))
    provenance = tuple(provenance)

    if sha:
        try:
            disk = worktree(SHARD)
        except OSError:
            disk = MISSING
        reach = {}
        for p, _r, _f in REACH:
            try:                                  # so L8's unreadable arm is live code, not dead
                reach[p] = blob("%s:%s" % (sha, p))
            except SystemExit:
                reach[p] = None
        return (blob("%s^:%s" % (sha, LIVE)), blob("%s:%s" % (sha, LIVE)),
                blob("%s:%s" % (sha, SHARD)), blob("%s:%s" % (sha, CLAUDE)),
                "the trim commit %s" % sha[:7], sha, disk, reach, lineage, provenance)
    reach = {}
    for p, _r, _f in REACH:
        try:
            reach[p] = worktree(p)
        except OSError:
            reach[p] = None
    return (blob("HEAD:%s" % LIVE), worktree(LIVE), worktree(SHARD), worktree(CLAUDE),
            "HEAD vs the working tree (trim not yet committed)", None, NA, reach, lineage,
            provenance)


def self_test(before, after, shard, claude, sha, reach, lineage, provenance):
    _, ar, _ = zones(after)
    sf, sr, _ = zones(shard)
    purpose = next(ln for ln in zones(before)[0].splitlines() if ln.startswith("**Purpose:**"))

    def sub_in_shard(o, n, count=1):
        assert o in shard, "self-test fixture missing: %r" % o[:40]
        return shard.replace(o, n, count)

    assert "−" in "".join(sr), "self-test fixture missing: no U+2212 in the archived span"
    assert "−" not in sf, "fixture broken: M9 must mutate a RECORD, not the shard banner"

    # M13's fixture: a front-matter sentence that is NOT in the pointer block and NOT touched by any
    # declared substitution, so mutating it is a genuinely UNDECLARED front-matter edit.
    UNDECL = "this paragraph is the only warning there is."
    assert after.count(UNDECL) == 1 and UNDECL not in POINTER, "M13 fixture broken"
    for _o, n in FRONT_SUBST:
        assert UNDECL not in n, "M13 fixture broken: it sits inside a declared substitution"

    # Every clause a mutant rewrites must be unambiguous in every text that carries it.
    CL216  = "**N ≤ 216** → `SESSION_NOTES-through-S216.md`"
    CL220  = "**217 ≤ N ≤ 220** → `SESSION_NOTES-S220-through-S217.md`"
    CL224  = "**221 ≤ N ≤ 224** → `SESSION_NOTES-S224-through-S221.md`"
    CL227  = "**225 ≤ N ≤ 227** → `SESSION_NOTES-S227-through-S225.md`"
    CL231  = "**228 ≤ N ≤ 231** → `SESSION_NOTES-S231-through-S228.md`"
    CL235  = "**232 ≤ N ≤ 235** → `SESSION_NOTES-S235-through-S232.md`"
    CL238  = "**236 ≤ N ≤ 238** → `SESSION_NOTES-S238-through-S236.md`"
    CL241  = "**239 ≤ N ≤ 241** → `SESSION_NOTES-S241-through-S239.md`"
    CLLIVE = "**N ≥ 242** → `SESSION_NOTES.md`"
    for cl in (CL216, CL220, CL224, CL227, CL231, CL235, CL238, CL241, CLLIVE):
        for name, text in (("POINTER", POINTER), ("BANNER", BANNER),
                           ("live file", after), ("shard", shard), ("CLAUDE.md", claude)):
            assert text.count(cl) == 1, ("self-test fixture %r occurs %d times in %s (want 1)"
                                         % (cl[:28], text.count(cl), name))

    def rewrite(pairs, texts):
        """Apply the same clause rewrites to every text that carries the table."""
        out = []
        for t in texts:
            for o, n in pairs:
                t = t.replace(o, n, 1)
            out.append(t)
        return out

    # --- L5 fixtures. Each rewrites the DECLARATION and the artifact together, so the assertion
    #     that pins them by equality (L2 for the pointer, L6 for the banner) stays satisfied and
    #     L5 is the only one left able to object.
    m18_b, m18_s = rewrite([(CLLIVE, "**N ≥ 239** → `SESSION_NOTES.md`")], [BANNER, shard])
    m19_b, m19_s = rewrite([(CL241, "**238 ≤ N ≤ 241** → `SESSION_NOTES-S241-through-S239.md`")],
                           [BANNER, shard])
    m20_p, m20_a = rewrite([(CLLIVE, "**N ≥ 239** → `SESSION_NOTES.md`")], [POINTER, after])
    m21_p, m21_a = rewrite([(CL241, "**240 ≤ N ≤ 241** → `SESSION_NOTES-S241-through-S239.md`")],
                           [POINTER, after])
    swap = [(CL238, "**236 ≤ N ≤ 238** → `SESSION_NOTES-S241-through-S239.md`"),
            (CL241, "**239 ≤ N ≤ 241** → `SESSION_NOTES-S238-through-S236.md`")]
    m22_b, m22_s = rewrite(swap, [BANNER, shard])
    m23_p, m23_a = rewrite(swap, [POINTER, after])

    # M24/M25/M38/M39/M47/M52 rewrite ROUTING as well, so even the declaration is self-consistent.
    BASE_R = ((None, 216, "SESSION_NOTES-through-S216.md"),
              (217, 220, "SESSION_NOTES-S220-through-S217.md"),
              (221, 224, "SESSION_NOTES-S224-through-S221.md"),
              (225, 227, "SESSION_NOTES-S227-through-S225.md"),
              (228, 231, "SESSION_NOTES-S231-through-S228.md"),
              (232, 235, "SESSION_NOTES-S235-through-S232.md"),
              (236, 238, "SESSION_NOTES-S238-through-S236.md"),
              (239, 241, "SESSION_NOTES-S241-through-S239.md"),
              (242, None, "SESSION_NOTES.md"))

    def routing_with(*repl):
        out = list(BASE_R)
        for idx, clause in repl:
            out[idx] = clause
        return tuple(out)

    short = [(CL241, "**239 ≤ N ≤ 240** → `SESSION_NOTES-S241-through-S239.md`"),
             (CLLIVE, "**N ≥ 241** → `SESSION_NOTES.md`")]
    m24_p, m24_b, m24_a, m24_s, m24_c = rewrite(short, [POINTER, BANNER, after, shard, claude])
    m24_r = routing_with((7, (239, 240, "SESSION_NOTES-S241-through-S239.md")),
                         (8, (241, None, "SESSION_NOTES.md")))
    front = [(CL216, "**N ≤ 100** → `SESSION_NOTES-through-S216.md`"),
             (CL220, "**101 ≤ N ≤ 220** → `SESSION_NOTES-S220-through-S217.md`")]
    m25_p, m25_b, m25_a, m25_s, m25_c = rewrite(front, [POINTER, BANNER, after, shard, claude])
    m25_r = routing_with((0, (None, 100, "SESSION_NOTES-through-S216.md")),
                         (1, (101, 220, "SESSION_NOTES-S220-through-S217.md")))
    gap = [(CL224, "**221 ≤ N ≤ 223** → `SESSION_NOTES-S224-through-S221.md`")]
    m38_p, m38_b, m38_a, m38_s, m38_c = rewrite(gap, [POINTER, BANNER, after, shard, claude])
    m38_r = routing_with((2, (221, 223, "SESSION_NOTES-S224-through-S221.md")))
    over = [(CL224, "**221 ≤ N ≤ 225** → `SESSION_NOTES-S224-through-S221.md`")]
    m39_p, m39_b, m39_a, m39_s, m39_c = rewrite(over, [POINTER, BANNER, after, shard, claude])
    m39_r = routing_with((2, (221, 225, "SESSION_NOTES-S224-through-S221.md")))
    shape = [(CL224, "**N ≤ 224** → `SESSION_NOTES-S224-through-S221.md`")]
    m47_p, m47_b, m47_a, m47_s, m47_c = rewrite(shape, [POINTER, BANNER, after, shard, claude])
    m47_r = routing_with((2, (None, 224, "SESSION_NOTES-S224-through-S221.md")))

    # M16/M17 move ONE WHOLE RECORD across the boundary. Both keep the newest-on-top order intact —
    # which is exactly why L1 and L3 cannot see them and L4 must.
    m16_after, m16_shard = after.replace(ar[-1], "", 1), sf + ar[-1] + "".join(sr)
    m17_after, m17_shard = after + sr[0], shard.replace(sr[0], "", 1)

    # --- L8 fixtures. Each mutates ONE of the four out-of-reach files.
    def reach_with(path, old, new, count=1):
        assert reach[path].count(old) >= 1, "self-test fixture missing in %s: %r" % (path, old[:50])
        r = dict(reach)
        r[path] = r[path].replace(old, new, count)
        return r
    m31 = reach_with(README, "older in the eight shards above", "older in the seven shards above")
    m32 = reach_with(README, REACH[0][1][0], "")
    m33 = reach_with(CONVENTIONS, "**Eight instances so far**", "**Seven instances so far**")
    m34 = reach_with(CONVENTIONS, "`SESSION_NOTES-S241-through-S239.md` (Session 245,",
                     "`SESSION_NOTES-S240-through-S239.md` (Session 245,")
    m41 = reach_with(BACKLOG, "there are now **eight** unwatched shards",
                     "there are now **seven** unwatched shards")
    # M42 removes the new shard's NAME from BACKLOG.md while leaving its size figure in place. It
    # therefore trips L8/set AND L12/prose; recorded rather than contrived, since M45 and M46 give
    # L8/set mutants of its own.
    m42 = reach_with(BACKLOG, "`SESSION_NOTES-S241-through-S239.md` (792 lines)",
                     "the newest shard (792 lines)")

    m43 = dict(reach)                                    # CLAUDE.md: table intact, count words stale
    m43[CLAUDE] = (m43[CLAUDE]
                   .replace("**Trimmed eight times (Sessions 222, 224, 228, 231, 235, 239, 242, 245):**",
                            "**Trimmed seven times (Sessions 222, 224, 228, 231, 235, 239, 242):**", 1)
                   .replace("Retired records live in **eight** write-once shards",
                            "Retired records live in **seven** write-once shards", 1)
                   .replace("grep *all eight*", "grep *all seven*", 1)
                   .replace("there are EIGHT, and a lookup must consult all of them",
                            "there are SEVEN, and a lookup must consult all of them", 1))
    # forbidden ALONE: the required string stays, the falsified one comes back beside it.
    m44 = reach_with(CONVENTIONS, "**Eight instances so far**",
                     "**Eight instances so far** — it said **Seven instances so far** before this cut")
    # set ALONE: an ANCESTOR's name typo'd where L14 reads no literal — L14's CONVENTIONS literals
    # are the `(Session N, Sessions A→B)` parentheticals, which this leaves untouched.
    m45 = reach_with(CONVENTIONS, "`SESSION_NOTES-S224-through-S221.md` (Session 228",
                     "`SESSION_NOTES-S224-through-S220.md` (Session 228")
    # set, via the lookahead: drop an ancestor's own repo-map line and leave its `.verify.sh` line.
    # L14 reads that line's span, so the declaration must lose it in the same breath — the entry is
    # replaced by a DUPLICATE of another README entry, which keeps len(LINEAGE_PROSE) and the figure
    # count intact so L14/census stays green and L8/set is the sole objector. S224 is still covered
    # by the CONVENTIONS, BACKLOG and CLAUDE entries, so L14/set stays green too.
    M46_LINE = ("  SESSION_NOTES-S224-through-S221.md    # frozen SESSION_NOTES records, "
                "Sessions 224->221 (grep it; do not Read it)\n")
    m46 = reach_with(README, M46_LINE, "")
    _dup = next(e for e in LINEAGE_PROSE
                if e[0] == README and e[1].startswith("Sessions 227->225"))
    m46_lp = tuple(_dup if (w == README and l.startswith("Sessions 224->221")) else (w, l, s, p)
                   for w, l, s, p in LINEAGE_PROSE)
    assert len(m46_lp) == len(LINEAGE_PROSE) and m46_lp != LINEAGE_PROSE, "M46 fixture is a no-op"

    # L9's third arm: git knows the file but no commit that added it. It reaches L14/blob too —
    # a shard with no add-commit cannot be measured — and that overlap is recorded, not contrived
    # apart: L14/blob's other reachable state (a declaration naming a shard the lineage lacks) is
    # M52's, and M52 keeps them aligned so it can isolate L5/4.
    m48 = tuple((p, None, d) if i == 0 else (p, c, d)
                for i, (p, c, d) in enumerate(lineage))
    # L8's unreadable arm — and L12's, L13's and L14's, all four now. Honest, not contrived: each
    # of those three reads a SUBSET of L8's four files, so a file only L8 reads cannot exist.
    m49 = {k: v for k, v in reach.items() if k != README}
    m49[README] = None
    # required ALONE: a declared string reworded so no forbidden string appears and the shard
    # name set stays complete.
    m50 = reach_with(CONVENTIONS, "**Eight instances so far**", "**8 instances so far**")

    # --- L9 fixtures. Same shape as L7's, one level out: the ANCESTOR shards on disk.
    def lineage_with(idx, mutate):
        out = list(lineage)
        path, committed, on_disk = out[idx]
        out[idx] = (path, committed, mutate(on_disk))
        return tuple(out)
    m35 = lineage_with(0, lambda t: t[:20000])
    m36 = lineage_with(1, lambda _t: MISSING)
    m37 = lineage_with(2, lambda t: t.replace("e", "3", 1))

    # M51 — L2/b3's narrowed form, and the only mutant that reaches it. A front-matter line is
    # COPIED into the banner (and into the declaration, so L6 is satisfied) and LEFT IN PLACE in
    # the live front matter, so b2's SURVIVAL arm has nothing to say and b1 sees an untouched
    # after_front. It REPLACES a banner line rather than appending one, so the shard's line count
    # is unchanged and L12 cannot steal it. The line it replaces is read by no other assertion.
    LINE = "assertions — which is worth knowing about what the assertions do and do not cover."
    assert BANNER.count(LINE) == 1 and purpose not in BANNER, "M51 fixture broken"
    m51_b = BANNER.replace(LINE, purpose, 1)
    m51_s = m51_b + "".join(sr)

    # M52 — L5/4's UNREADABLE arm, alone. An ancestor shard's filename is typo'd in the declaration
    # AND every prose copy AND all four REACH texts, so L5/1-L5/3 are self-consistent and L8/set
    # sees the same (wrong) name set the routing table does. At THIS trim it must also move
    # LINEAGE_PROSE's literals and shard keys AND the lineage path, or L14 objects first and this
    # mutant stops isolating anything — the seventh trim's version did not have to.
    TYPO = ("SESSION_NOTES-S220-through-S217.md", "SESSION_NOTES-S220-through-S218.md")
    m52_p, m52_b, m52_a, m52_s, m52_c = rewrite(
        [(CL220, CL220.replace(*TYPO))], [POINTER, BANNER, after, shard, claude])
    m52_r = tuple((lo, hi, d.replace(*TYPO)) for lo, hi, d in ROUTING)
    m52_reach = {k: (v.replace(*TYPO) if v is not None else None) for k, v in reach.items()}
    m52_lp = tuple((w, l.replace(*TYPO), s,
                    tuple((b.replace(*TYPO), f) for b, f in pr))
                   for w, l, s, pr in LINEAGE_PROSE)
    m52_lin = tuple((p.replace(*TYPO), c, d) for p, c, d in lineage)

    # M53/M54/M55 — L10's three arms, one each.
    def provenance_with(idx, committed=..., disk=...):
        out = list(provenance)
        c, d = out[idx][2], out[idx][3]
        out[idx] = (out[idx][0], out[idx][1],
                    c if committed is ... else committed,
                    d if disk is ... else disk)
        return tuple(out)
    m53 = provenance_with(0, committed=None)                       # declared freeze holds no blob
    m54 = provenance_with(1, disk=MISSING)                         # proof deleted from the tree
    m55 = provenance_with(6, disk=provenance[6][3][:12000])        # proof truncated on disk

    # M56/M57/M58/M59/M84 — L11's arms.
    trig, targ, floor, texts = POLICY

    def policy_with(idx, value, old_s, new_s):
        """Relax one retention integer AND the sentence that declares it, together — which is what
        a trim actually relaxing the rule would do. Moving the integer alone trips L11/figure."""
        assert texts[idx] == old_s and old_s in claude, "policy fixture broken at %d" % idx
        ts = tuple(new_s if i == idx else s for i, s in enumerate(texts))
        pol = tuple(value if i == idx else v for i, v in enumerate((trig, targ, floor))) + (ts,)
        return pol, claude.replace(old_s, new_s, 1)

    m56_pol, m56_c = policy_with(0, 5000, "Fire a new trim when the live file exceeds **1,500 lines**",
                                 "Fire a new trim when the live file exceeds **5,000 lines**")
    m57_pol, m57_c = policy_with(1, 500, "cut back to **≤1,050 lines**",
                                 "cut back to **≤500 lines**")
    m58_pol, m58_c = policy_with(2, 9, "never retain fewer than **4** sessions",
                                 "never retain fewer than **9** sessions")
    # M84 — L11/figure alone: the target is relaxed and `CLAUDE.md` is left saying 1,050.
    m84_pol = (trig, 900, floor, texts)
    m59_c = claude.replace("Fire a new trim when the live file exceeds **1,500 lines**",
                           "Fire a new trim when the live file feels too long", 1)

    # --- L12's arms. M60-M63 and M68 move ONE declared integer and leave every prose copy alone;
    #     M64-M67 move a FIGURE IN THE PROSE together with every declaration that pins that prose
    #     by equality, so L2/b1 and L6 stay satisfied and L12/prose is the only objector.
    def sizes_with(**kw):
        s = dict(SIZES)
        s.update(kw)
        return s

    def prose_with(old, new):
        assert any(old in l for _w, l, _f, _k in SIZE_PROSE), "fixture missing in SIZE_PROSE: %r" % old
        return tuple((w, l.replace(old, new, 1), f, k) for w, l, f, k in SIZE_PROSE)

    m60 = sizes_with(archived_headings=4)
    m61 = sizes_with(archived_lines=731)
    m62 = sizes_with(shard_total=792 + 10)
    m63_sz = sizes_with(read_cap=500)
    m63_b = BANNER.replace("under the 2,000-line agent read", "under the 500-line agent read", 1)
    m63_s = shard.replace("under the 2,000-line agent read", "under the 500-line agent read", 1)
    m63_pr = prose_with("At 792 lines it sits under the 2,000-line agent read",
                        "At 792 lines it sits under the 500-line agent read")
    m64_p = POINTER.replace("3 record headings, 721 lines", "3 record headings, 731 lines", 1)
    m64_a = after.replace("3 record headings, 721 lines", "3 record headings, 731 lines", 1)
    m64_pr = prose_with("3 record headings, 721 lines", "3 record headings, 731 lines")
    m65 = reach_with(BACKLOG, "`SESSION_NOTES-S241-through-S239.md` (792 lines)",
                     "`SESSION_NOTES-S241-through-S239.md` (463 lines)")
    m66 = reach_with(README, "newest 4 sessions", "newest 5 sessions")
    m67_b = BANNER.replace("— three record", "— four record", 1)
    m67_s = shard.replace("— three record", "— four record", 1)
    m67_pr = prose_with("— three record", "— four record")
    m68 = sizes_with(retained_records=5)

    # --- L13's arms, inherited from the seventh trim and rebased to this cut's spans.
    def span_with(old, new):
        assert any(old in l for _w, l, _s, _k in SPAN_PROSE), "fixture missing in SPAN_PROSE: %r" % old
        return tuple((w, l.replace(old, new, 1), s, k) for w, l, s, k in SPAN_PROSE)

    m69_base = "SESSION_NOTES-S241-through-S238.md"
    m70_p = POINTER.replace("Archived Sessions 241 → 239 —", "Archived Sessions 241 → 238 —", 1)
    m70_a = after.replace("Archived Sessions 241 → 239 —", "Archived Sessions 241 → 238 —", 1)
    m70_sp = span_with("Archived Sessions 241 → 239 —", "Archived Sessions 241 → 238 —")
    m71_b = BANNER.replace("archive shard: Sessions 241 → 239",
                           "archive shard: Sessions 241 → 240", 1)
    m71_s = shard.replace("archive shard: Sessions 241 → 239",
                          "archive shard: Sessions 241 → 240", 1)
    m71_sp = span_with("archive shard: Sessions 241 → 239", "archive shard: Sessions 241 → 240")
    m72 = reach_with(README, "Sessions 241->239 (grep it; do not Read it)",
                     "Sessions 241->238 (grep it; do not Read it)")
    m73_p = POINTER.replace("holds Sessions 245 → 242 only", "holds Sessions 245 → 243 only", 1)
    m73_a = after.replace("holds Sessions 245 → 242 only", "holds Sessions 245 → 243 only", 1)
    m73_sp = span_with("holds Sessions 245 → 242 only", "holds Sessions 245 → 243 only")
    m74 = reach_with(CONVENTIONS, "(Session 245, Sessions 241→239)",
                     "(Session 245, Sessions 241→240)")
    # The word this mutant moves MUST be the one WORDS renders for len(SPAN_PROSE).
